// Package broker is the fileprotov2 client of the files subsystem
// (SYN-27): batch RPCs against the space's responsible fileV2 nodes
// (routing by nodeconf.FileV2Peers with NotResponsible failover), the
// presigned HTTP upload, and durable-custody receipt verification
// against the fleet.
//
// Per-item outcomes (fileprotov2.ErrCode in the response body) are the
// caller's business — this package only routes whole-RPC errors.
package broker

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"slices"
	"sync"
	"sync/atomic"
	"time"

	"github.com/anyproto/any-sync/commonfile/fileproto/fileprotov2"
	"github.com/anyproto/any-sync/commonfile/fileproto/fileprotov2/fileprotov2err"
	"github.com/anyproto/any-sync/net/pool"
	"github.com/anyproto/any-sync/net/rpc/rpcerr"
	"github.com/ipfs/go-cid"
	"storj.io/drpc"
)

// ErrPutStalled — a presigned upload made no progress for
// putStallTimeout and was aborted.
var ErrPutStalled = errors.New("filebroker: presigned PUT stalled")

// ErrNoFileNodes — the network configuration lists no fileV2 nodes;
// files can be registered but never made durable.
var ErrNoFileNodes = errors.New("filebroker: no fileV2 nodes in network config")

// Client speaks fileprotov2 to the network's fileV2 fleet. Safe for
// concurrent use.
type Client struct {
	pool          pool.Pool
	peers         func() []string
	networkId     string
	fileNetworkId func() string
	hc            *http.Client

	// quotaPeer is the node that last answered SpaceQuota.
	quotaMu   sync.Mutex
	quotaPeer string
}

// New builds a Client. peers must return the current fileV2 fleet
// (nodeconf.FileV2Peers) and fileNetworkId the fleet's receipt-signing
// identity (nodeconf.Configuration().FileNetworkId) — both funcs so
// nodeconf reloads are picked up.
func New(p pool.Pool, peers func() []string, networkId string, fileNetworkId func() string) *Client {
	return &Client{pool: p, peers: peers, networkId: networkId, fileNetworkId: fileNetworkId, hc: http.DefaultClient}
}

// NetworkId returns the network the client verifies receipts against.
func (c *Client) NetworkId() string { return c.networkId }

// do runs fn against the fleet: peers are tried in order, failing over
// on dial errors and on the whole-RPC NotResponsible routing signal;
// any other RPC error is final (auth / malformed — another peer would
// answer the same).
func (c *Client) do(ctx context.Context, fn func(cl fileprotov2.DRPCFileV2Client) error) error {
	peers := c.peers()
	if len(peers) == 0 {
		return ErrNoFileNodes
	}
	var lastErr error
	for _, peerId := range peers {
		pr, err := c.pool.Get(ctx, peerId)
		if err != nil {
			lastErr = err
			continue
		}
		err = pr.DoDrpc(ctx, func(conn drpc.Conn) error {
			return fn(fileprotov2.NewDRPCFileV2Client(conn))
		})
		if err == nil {
			return nil
		}
		lastErr = err
		if errors.Is(rpcerr.Unwrap(err), fileprotov2err.ErrNotResponsible) {
			continue
		}
		return err
	}
	return lastErr
}

// Info fetches the node-level metadata (publicReadBaseUrl et al) from
// any responsible node.
func (c *Client) Info(ctx context.Context) (resp *fileprotov2.InfoResponse, err error) {
	err = c.do(ctx, func(cl fileprotov2.DRPCFileV2Client) error {
		resp, err = cl.Info(ctx, &fileprotov2.InfoRequest{})
		return err
	})
	return resp, err
}

// Upload requests presigned upload targets for a batch of roots.
func (c *Client) Upload(ctx context.Context, spaceId string, items []*fileprotov2.UploadRequestItem) (resp *fileprotov2.UploadResponse, err error) {
	err = c.do(ctx, func(cl fileprotov2.DRPCFileV2Client) error {
		resp, err = cl.Upload(ctx, &fileprotov2.UploadRequest{SpaceId: spaceId, Items: items})
		return err
	})
	return resp, err
}

// RequestSign requests durable-custody receipts for a batch of roots.
func (c *Client) RequestSign(ctx context.Context, spaceId string, rootCids [][]byte) (resp *fileprotov2.RequestSignResponse, err error) {
	err = c.do(ctx, func(cl fileprotov2.DRPCFileV2Client) error {
		resp, err = cl.RequestSign(ctx, &fileprotov2.RequestSignRequest{SpaceId: spaceId, RootCids: rootCids})
		return err
	})
	return resp, err
}

// SpaceInfo fetches quota state for a batch of spaces.
func (c *Client) SpaceInfo(ctx context.Context, spaceIds []string) (resp *fileprotov2.SpaceInfoResponse, err error) {
	err = c.do(ctx, func(cl fileprotov2.DRPCFileV2Client) error {
		resp, err = cl.SpaceInfo(ctx, &fileprotov2.SpaceInfoRequest{SpaceIds: spaceIds})
		return err
	})
	return resp, err
}

// quotaHedge is how long a silent node is waited for before the next one
// is asked too. A healthy node answers well within it, its own
// coordinator lookup included.
const quotaHedge = 1500 * time.Millisecond

// SpaceQuota fetches one space's quota. The fleet is asked one node
// after another, starting with the node that answered last time, and
// the first usable answer wins: a node that fails or does not take the
// space passes the turn at once, a silent one after quotaHedge. With no
// usable answer it returns an unusable one, if a node gave any.
func (c *Client) SpaceQuota(ctx context.Context, spaceId string, usable func(*fileprotov2.SpaceQuota) bool) (*fileprotov2.SpaceQuota, error) {
	return c.quotaFrom(ctx, usable, func(ctx context.Context, peerId string) (*fileprotov2.SpaceQuota, error) {
		return c.askQuota(ctx, peerId, spaceId)
	})
}

// quotaFrom walks the fleet with ask and remembers the node that gave a
// usable answer.
func (c *Client) quotaFrom(
	ctx context.Context,
	usable func(*fileprotov2.SpaceQuota) bool,
	ask func(ctx context.Context, peerId string) (*fileprotov2.SpaceQuota, error),
) (*fileprotov2.SpaceQuota, error) {
	peers := c.peers()
	if len(peers) == 0 {
		return nil, ErrNoFileNodes
	}
	c.quotaMu.Lock()
	peers = peerFirst(peers, c.quotaPeer)
	c.quotaMu.Unlock()
	quota, peerId, err := hedgeQuota(ctx, peers, quotaHedge, ask, usable)
	if err == nil && usable(quota) {
		c.quotaMu.Lock()
		c.quotaPeer = peerId
		c.quotaMu.Unlock()
	}
	return quota, err
}

// peerFirst returns peers with first, when it is one of them, in front.
func peerFirst(peers []string, first string) []string {
	i := slices.Index(peers, first)
	if i <= 0 {
		return peers
	}
	out := make([]string, 0, len(peers))
	out = append(out, first)
	out = append(out, peers[:i]...)
	return append(out, peers[i+1:]...)
}

// askQuota asks one node. SpaceInfo reports a misrouted space per item.
func (c *Client) askQuota(ctx context.Context, peerId, spaceId string) (*fileprotov2.SpaceQuota, error) {
	pr, err := c.pool.Get(ctx, peerId)
	if err != nil {
		return nil, err
	}
	var resp *fileprotov2.SpaceInfoResponse
	err = pr.DoDrpc(ctx, func(conn drpc.Conn) error {
		var rpcErr error
		resp, rpcErr = fileprotov2.NewDRPCFileV2Client(conn).SpaceInfo(ctx, &fileprotov2.SpaceInfoRequest{SpaceIds: []string{spaceId}})
		return rpcErr
	})
	if err != nil {
		return nil, rpcerr.Unwrap(err)
	}
	quota, code := spaceQuotaOf(resp, spaceId)
	switch code {
	case fileprotov2.ErrCode_Ok:
		return quota, nil
	case fileprotov2.ErrCode_ErrNotResponsible:
		return nil, fileprotov2err.ErrNotResponsible
	default:
		return nil, fmt.Errorf("filebroker: space info %s: %s", spaceId, code)
	}
}

// hedgeQuota asks the peers in order and returns the first usable answer
// with the peer that gave it. The next peer is asked as soon as one
// answers without a usable quota, and after hedge while the ones asked
// stay silent. Failing a usable answer it returns an unusable one;
// failing that an error, which is ErrNotResponsible only when every
// peer refused the space.
func hedgeQuota(
	ctx context.Context,
	peers []string,
	hedge time.Duration,
	ask func(ctx context.Context, peerId string) (*fileprotov2.SpaceQuota, error),
	usable func(*fileprotov2.SpaceQuota) bool,
) (*fileprotov2.SpaceQuota, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	type answer struct {
		peerId string
		quota  *fileprotov2.SpaceQuota
		err    error
	}
	answers := make(chan answer, len(peers))
	asked := 0
	askNext := func() {
		peerId := peers[asked]
		asked++
		go func() {
			quota, err := ask(ctx, peerId)
			answers <- answer{peerId, quota, err}
		}()
	}
	askNext()
	timer := time.NewTimer(hedge)
	defer timer.Stop()

	var (
		unusable     *fileprotov2.SpaceQuota
		unusablePeer string
		failure      error
	)
	for answered := 0; answered < len(peers); {
		select {
		case <-ctx.Done():
			return nil, "", ctx.Err()
		case a := <-answers:
			answered++
			switch {
			case a.err == nil && usable(a.quota):
				return a.quota, a.peerId, nil
			case a.err == nil:
				unusable, unusablePeer = a.quota, a.peerId
			case failure == nil || errors.Is(failure, fileprotov2err.ErrNotResponsible):
				failure = a.err
			}
		case <-timer.C:
		}
		if asked < len(peers) {
			askNext()
			timer.Reset(hedge)
		}
	}
	if unusable != nil {
		return unusable, unusablePeer, nil
	}
	return nil, "", failure
}

// spaceQuotaOf picks spaceId's result out of a SpaceInfo response.
func spaceQuotaOf(resp *fileprotov2.SpaceInfoResponse, spaceId string) (*fileprotov2.SpaceQuota, fileprotov2.ErrCode) {
	for _, res := range resp.GetResults() {
		if res.GetSpaceId() != spaceId {
			continue
		}
		if res.GetCode() == fileprotov2.ErrCode_Ok && res.GetQuota() == nil {
			return nil, fileprotov2.ErrCode_ErrUnexpected
		}
		return res.GetQuota(), res.GetCode()
	}
	return nil, fileprotov2.ErrCode_ErrUnexpected
}

// putStallTimeout aborts a presigned upload that moves no byte and
// gets no answer for this long: an upload has no overall deadline worth
// the name (size and uplink vary by orders of magnitude), so progress is
// what is bounded.
var putStallTimeout = time.Minute

// progressReader stamps every read so a watchdog can tell a slow
// transfer from a dead one.
type progressReader struct {
	r    io.Reader
	last atomic.Int64 // unix nanos of the last read
}

func (p *progressReader) Read(b []byte) (int, error) {
	n, err := p.r.Read(b)
	p.last.Store(time.Now().UnixNano())
	return n, err
}

// Put performs the presigned upload: the exact body bytes, provider
// fields sent verbatim as headers, Content-Length set explicitly (the
// presign enforces the cap server-side; we fail fast locally). A
// transfer stalled for putStallTimeout is aborted.
func (c *Client) Put(ctx context.Context, up *fileprotov2.PresignedUpload, body io.Reader, size int64) error {
	if up == nil || up.Url == "" {
		return errors.New("filebroker: empty presigned upload")
	}
	if up.MaxContentLength > 0 && uint64(size) > up.MaxContentLength {
		return fmt.Errorf("filebroker: body %d bytes exceeds presign cap %d", size, up.MaxContentLength)
	}
	ctx, cancel := context.WithCancelCause(ctx)
	defer cancel(nil)
	pr := &progressReader{r: body}
	pr.last.Store(time.Now().UnixNano())
	stall := putStallTimeout
	go func() {
		tick := time.NewTicker(stall / 4)
		defer tick.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-tick.C:
				if time.Since(time.Unix(0, pr.last.Load())) > stall {
					cancel(ErrPutStalled)
					return
				}
			}
		}
	}()
	req, err := http.NewRequestWithContext(ctx, http.MethodPut, up.Url, pr)
	if err != nil {
		return err
	}
	req.ContentLength = size
	for _, f := range up.Fields {
		req.Header.Set(f.Key, f.Value)
	}
	resp, err := c.hc.Do(req)
	if err != nil {
		if cause := context.Cause(ctx); errors.Is(cause, ErrPutStalled) {
			return cause
		}
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		msg, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
		return fmt.Errorf("filebroker: presigned PUT: %d %s", resp.StatusCode, string(msg))
	}
	return nil
}

// VerifyReceipt validates a durable-custody receipt for (spaceId,
// root, objectSize) against this network's fleet key and returns the
// networkSign row value ("{fileNetworkId}/{base64(signature)}").
func (c *Client) VerifyReceipt(rcpt *fileprotov2.NetworkSignReceipt, spaceId string, root cid.Cid, objectSize uint64) (string, error) {
	return VerifyReceipt(rcpt, VerifyParams{
		NetworkId:     c.networkId,
		SpaceId:       spaceId,
		Root:          root,
		ObjectSize:    objectSize,
		FileNetworkId: c.fileNetworkId(),
	})
}

package broker

import (
	"context"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/anyproto/any-sync/commonfile/fileproto/fileprotov2"
)

// An already-cancelled lookup must not launch even a cooperative peer.
func TestPinkhaQuotaHedgePreCancelledSkipsFleet(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	var calls atomic.Int32

	quota, peer, err := hedgeQuota(ctx, []string{"a", "b"}, time.Hour,
		func(ctx context.Context, _ string) (*fileprotov2.SpaceQuota, error) {
			calls.Add(1)
			return nil, ctx.Err()
		},
		func(q *fileprotov2.SpaceQuota) bool { return q != nil })

	if err != context.Canceled || quota != nil || peer != "" {
		t.Fatalf("cancelled lookup returned quota=%v peer=%q err=%v", quota, peer, err)
	}
	if got := calls.Load(); got != 0 {
		t.Fatalf("cancelled lookup started %d peer calls", got)
	}
}

// Cancelling the coordinator does not terminate an arbitrary callback. This
// test holds that callback explicitly, checks the coordinator first, and then
// releases the callback and joins the coordinator. Cleanup observes callback
// return if callback entry was seen; early entry failures make that observation
// conditional. It does not observe the private sender's final instruction. The
// original len(peers)-buffered channel has room for every late answer.
func TestPinkhaQuotaHedgeEndsBeforeBlockedPeerReturns(t *testing.T) {
	for _, tc := range []struct {
		name     string
		deadline bool
		want     error
	}{
		{name: "cancel", want: context.Canceled},
		{name: "deadline", deadline: true, want: context.DeadlineExceeded},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var ctx context.Context
			var cancel context.CancelFunc
			if tc.deadline {
				ctx, cancel = context.WithTimeout(context.Background(), 5*time.Second)
			} else {
				ctx, cancel = context.WithCancel(context.Background())
			}
			entered := make(chan struct{})
			release := make(chan struct{})
			peerReturned := make(chan struct{})
			coordinatorDone := make(chan struct{})
			var releaseOnce sync.Once
			type answer struct {
				quota *fileprotov2.SpaceQuota
				peer  string
				err   error
			}
			result := make(chan answer, 1)

			t.Cleanup(func() {
				cancel()
				releaseOnce.Do(func() { close(release) })
				select {
				case <-coordinatorDone:
				case <-time.After(2 * time.Second):
					t.Error("test-owned coordinator did not stop after peer release")
				}
				select {
				case <-entered:
					select {
					case <-peerReturned:
					case <-time.After(2 * time.Second):
						t.Error("test-owned peer did not return after release")
					}
				default:
				}
			})

			go func() {
				defer close(coordinatorDone)
				quota, peer, err := hedgeQuota(ctx, []string{"held-peer"}, time.Hour,
					func(context.Context, string) (*fileprotov2.SpaceQuota, error) {
						close(entered)
						defer close(peerReturned)
						<-release
						return &fileprotov2.SpaceQuota{AccountLimitBytes: 123}, nil
					},
					func(q *fileprotov2.SpaceQuota) bool { return q != nil })
				result <- answer{quota, peer, err}
			}()

			select {
			case <-entered:
			case <-time.After(2 * time.Second):
				t.Fatal("peer callback did not start")
			}
			if !tc.deadline {
				cancel()
			}
			select {
			case <-ctx.Done():
			case <-time.After(7 * time.Second):
				t.Fatal("test context did not end")
			}
			select {
			case got := <-result:
				if got.err != tc.want || got.quota != nil || got.peer != "" {
					t.Fatalf("ended lookup returned quota=%v peer=%q err=%v", got.quota, got.peer, got.err)
				}
			case <-time.After(2 * time.Second):
				t.Fatal("quota coordinator waited for a peer after its context ended")
			}
			select {
			case <-peerReturned:
				t.Fatal("callback returned before its independent release")
			default:
			}
		})
	}
}
